//github.com/shadcn-ui/ui/blob/HEAD/apps/v4/registry/new-york-v4/examples/badge-demo.tsx\nimport { AlertCircleIcon, BadgeCheckIcon, CheckIcon } from \"lucide-react\"\n\nimport { Badge } from \"@/registry/new-york-v4/ui/badge\"\n\nexport default function BadgeDemo() {\n  return (\n    <div className=\"flex flex-col items-center gap-2\">\n      <div className=\"flex w-full flex-wrap gap-2\">\n        <Badge>Badge</Badge>\n        <Badge variant=\"secondary\">Secondary</Badge>\n        <Badge variant=\"destructive\">Destructive</Badge>\n        <Badge variant=\"outline\">Outline</Badge>\n      </div>\n      <div className=\"flex w-full flex-wrap gap-2\">\n        <Badge\n          variant=\"secondary\"\n          className=\"bg-blue-500 text-white dark:bg-blue-600\"\n        >\n          <BadgeCheckIcon />\n          Verified\n        </Badge>\n        <Badge className=\"h-5 min-w-5 rounded-full px-1 font-mono tabular-nums\">\n          8\n        </Badge>\n        <Badge\n          className=\"h-5 min-w-5 rounded-full px-1 font-mono tabular-nums\"\n          variant=\"destructive\"\n        >\n          99\n        </Badge>\n        <Badge\n          className=\"h-5 min-w-5 rounded-full px-1 font-mono tabular-nums\"\n          variant=\"outline\"\n        >\n          20+\n        </Badge>\n      </div>\n    </div>\n  )\n}", "cs": "https://github.com/shadcn-ui/ui/blob/HEAD/apps/v4/registry/new-york-v4/examples/badge-demo.tsx", "cl": "MIT", "sup": "# 聚合站补充 · Hub notes\n# 原站文档 Docs: https://ui.shadcn.com/docs/components/base/badge#rtl\n# 许可 License: MIT · 框架 Framework: React\n# 以上「原站原文」逐字来自官方仓库/文档（每段标了来源）；完整变体与 API 请看原站。\n# 本站不提供任何付费模板 / Pro 组件源码。", "fw": "React", "full": 1}, "cs2-magicui-design--dialog--hero-video-dialog--v1": {"d": "A hero video dialog component.", "ds": "https://magicui.design/docs/components/hero-video-dialog", "c": "# ① 安装 Install — https://github.com/magicuidesign/magicui#readme\nnpx shadcn@latest add \"https://magicui.design/r/marquee.json\"\n\n// ④ 示例 Example · 官方文档示例 — https://magicui.design/docs/components/hero-video-dialog#top-in-bottom-out\nimport { HeroVideoDialog } from \"@/registry/magicui/hero-video-dialog\"\n\nexport function HeroVideoDialogDemo() {\n  return (\n    <div className=\"relative\">\n      <HeroVideoDialog\n        className=\"block dark:hidden\"\n        animationStyle=\"from-center\"\n        videoSrc=\"https://www.youtube.com/embed/qh3NGpYRG3I?si=4rb-zSdDkVK9qxxb\"\n        thumbnailSrc=\"https://startup-template-sage.vercel.app/hero-light.png\"\n        thumbnailAlt=\"Hero Video\"\n      />\n      <HeroVideoDialog\n        className=\"hidden dark:block\"\n        animationStyle=\"from-center\"\n        videoSrc=\"https://www.youtube.com/embed/qh3NGpYRG3I?si=4rb-zSdDkVK9qxxb\"\n        thumbnailSrc=\"https://startup-template-sage.vercel.app/hero-dark.png\"\n        thumbnailAlt=\"Hero Video\"\n      />\n    </div>\n  )\n}\n\nimport { HeroVideoDialog } from \"@/registry/magicui/hero-video-dialog\"\n\nexport function HeroVideoDialogDemoTopInBottomOut() {\n  return (\n    <div className=\"relative\">\n      <HeroVideoDialog\n        className=\"block dark:hidden\"\n        animationStyle=\"top-in-bottom-out\"\n        videoSrc=\"https://www.youtube.com/embed/qh3NGpYRG3I?si=4rb-zSdDkVK9qxxb\"\n        thumbnailSrc=\"https://startup-template-sage.vercel.app/hero-light.png\"\n        thumbnailAlt=\"Hero Video\"\n      />\n      <HeroVideoDialog\n        className=\"hidden dark:block\"\n        animationStyle=\"top-in-bottom-out\"\n        videoSrc=\"https://www.youtube.com/embed/qh3NGpYRG3I?si=4rb-zSdDkVK9qxxb\"\n        thumbnailSrc=\"https://startup-template-sage.vercel.app/hero-dark.png\"\n        thumbnailAlt=\"Hero Video\"\n      />\n    </div>\n  )\n}", "cs": "https://magicui.design/docs/components/hero-video-dialog#top-in-bottom-out", "cl": "MIT", "sup": "# 聚合站补充 · Hub notes\n# 原站文档 Docs: https://magicui.design/docs/components/hero-video-dialog#top-in-bottom-out\n# 许可 License: MIT\n# 以上「原站原文」逐字来自官方仓库/文档（每段标了来源）；完整变体与 API 请看原站。\n# 不含付费部分：Magic UI Pro 模板（请到原站购买）。", "full": 1}, "cs2-lib-www-spartan-ng--tabs--tabs--v1": {"d": "A set of layered sections of content—known as tab panels—that are displayed one at a time.", "ds": "https://www.spartan.ng/components/tabs", "c": "import { Component } from '@angular/core';\nimport { HlmButtonImports } from '@spartan-ng/helm/button';\nimport { HlmCardImports } from '@spartan-ng/helm/card';\nimport { HlmInputImports } from '@spartan-ng/helm/input';\nimport { HlmLabelImports } from '@spartan-ng/helm/label';\nimport { HlmTabsImports } from '@spartan-ng/helm/tabs';\n\n@Component({\n\tselector: 'spartan-tabs-preview',\n\timports: [HlmTabsImports, HlmCardImports, HlmLabelImports, HlmInputImports, HlmButtonImports],\n\thost: {\n\t\tclass: 'block w-full max-w-lg',\n\t},\n\ttemplate: `\n\t\t<hlm-tabs tab=\"account\" class=\"w-full\">\n\t\t\t<hlm-tabs-list aria-label=\"tabs example\">\n\t\t\t\t<button hlmTabsTrigger=\"account\">Account</button>\n\t\t\t\t<button hlmTabsTrigger=\"password\">Password</button>\n\t\t\t</hlm-tabs-list>\n\t\t\t<div hlmTabsContent=\"account\">\n\t\t\t\t<section hlmCard>\n\t\t\t\t\t<div hlmCardHeader>\n\t\t\t\t\t\t<h3 hlmCardTitle>Account</h3>\n\t\t\t\t\t\t<p hlmCardDescription>Make changes to your account here. Click save when you're done.</p>\n\t\t\t\t\t</div>\n\t\t\t\t\t<p hlmCardContent>\n\t\t\t\t\t\t<label class=\"my-4 block\" hlmLabel>\n\t\t\t\t\t\t\tName\n\t\t\t\t\t\t\t<input class=\"mt-1.5 w-full\" value=\"Pedro Duarte\" hlmInput />\n\t\t\t\t\t\t</label>\n\t\t\t\t\t\t<label class=\"my-4 block\" hlmLabel>\n\t\t\t\t\t\t\tUsername\n\t\t\t\t\t\t\t<input class=\"mt-1.5 w-full\" placeholder=\"@peduarte\" hlmInput />\n\t\t\t\t\t\t</label>\n\t\t\t\t\t</p>\n\t\t\t\t\t<div hlmCardFooter>\n\t\t\t\t\t\t<button hlmBtn>Save Changes</button>\n\t\t\t\t\t</div>\n\t\t\t\t</section>\n\t\t\t</div>\n\t\t\t<div hlmTabsContent=\"password\">\n\t\t\t\t<section hlmCard>\n\t\t\t\t\t<div hlmCardHeader>\n\t\t\t\t\t\t<h3 hlmCardTitle>Password</h3>\n\t\t\t\t\t\t<p hlmCardDescription>Change your password here. After saving, you'll be logged out.</p>\n\t\t\t\t\t</div>\n\t\t\t\t\t<p hlmCardContent>\n\t\t\t\t\t\t<label class=\"my-4 block\" hlmLabel>\n\t\t\t\t\t\t\tOld Password\n\t\t\t\t\t\t\t<input class=\"mt-1.5 w-full\" type=\"password\" hlmInput />\n\t\t\t\t\t\t</label>\n\t\t\t\t\t\t<label class=\"my-4 block\" hlmLabel>\n\t\t\t\t\t\t\tNew Password\n\t\t\t\t\t\t\t<input class=\"mt-1.5 w-full\" type=\"password\" hlmInput />\n\t\t\t\t\t\t</label>\n\t\t\t\t\t</p>\n\t\t\t\t\t<div hlmCardFooter>\n\t\t\t\t\t\t<button hlmBtn>Save Password</button>\n\t\t\t\t\t</div>\n\t\t\t\t</section>\n\t\t\t</div>\n\t\t</hlm-tabs>\n\t`,\n})\nexport class TabsPreview {}", "cs": "https://www.spartan.ng/components/tabs#examples__vertical", "cl": "MIT", "sup": "# 聚合站补充 · Hub notes\n# 原站文档 Docs: https://www.spartan.ng/components/tabs#examples__vertical\n# 许可 License: MIT\n# 以上「原站原文」逐字来自官方仓库/文档（每段标了来源）；完整变体与 API 请看原站。\n# 本站不提供任何付费模板 / Pro 组件源码。"}, "cs2-lib-www-shadcn-svelte-com--card--card--v1": {"d": "Displays a card with header, content, and footer.", "ds": "https://www.shadcn-svelte.com/docs/components/card", "c": "# ① 安装 Install — https://github.com/huntabyte/shadcn-svelte#readme\nnpx shadcn-svelte@latest init\n\n<!-- ④ 示例 Example · 官方文档示例 — https://www.shadcn-svelte.com/docs/components/card#size -->\n<script lang=\"ts\">\n  import * as Card from \"$lib/components/ui/card/index.js\";\n  import { Button } from \"$lib/components/ui/button/index.js\";\n  import { Input } from \"$lib/components/ui/input/index.js\";\n  import { Label } from \"$lib/components/ui/label/index.js\";\n</script>\n \n<Card.Root class=\"w-full max-w-sm\">\n  <Card.Header>\n    <Card.Title>Login to your account</Card.Title>\n    <Card.Description\n      >Enter your email below to login to your account</Card.Description\n    >\n    <Card.Action>\n      <Button variant=\"link\">Sign Up</Button>\n    </Card.Action>\n  </Card.Header>\n  <Card.Content>\n    <form>\n      <div class=\"flex flex-col gap-6\">\n        <div class=\"grid gap-2\">\n          <Label for=\"email\">Email</Label>\n          <Input id=\"email\" type=\"email\" placeholder=\"m@example.com\" required />\n        </div>\n        <div class=\"grid gap-2\">\n          <div class=\"flex items-center\">\n            <Label for=\"password\">Password</Label>\n            <a\n              href=\"##\"\n              class=\"ml-auto inline-block text-sm underline-offset-4 hover:underline\"\n            >\n              Forgot your password?\n            </a>\n          </div>\n          <Input id=\"password\" type=\"password\" required />\n        </div>\n      </div>\n    </form>\n  </Card.Content>\n  <Card.Footer class=\"flex-col gap-2\">\n    <Button type=\"submit\" class=\"w-full\">Login</Button>\n    <Button variant=\"outline\" class=\"w-full\">Login with Google</Button>\n  </Card.Footer>\n</Card.Root>\n\n<script lang=\"ts\">\n  import ChevronRightIcon from \"@lucide/svelte/icons/chevron-right\";\n  import * as Card from \"$lib/components/ui/card/index.js\";\n  import { Button } from \"$lib/components/ui/button/index.js\";\n \n  const featureName = \"Scheduled reports\";\n  const steps = [\n    \"Choose a schedule (daily, or weekly).\",\n    \"Send to channels or specific teammates.\",\n    \"Include charts, tables, and key metrics.\"\n  ];\n</script>\n \n<Card.Root size=\"sm\" class=\"mx-auto w-full max-w-xs\">\n  <Card.Header>\n    <Card.Title>{featureName}</Card.Title>\n    <Card.Description\n      >Weekly snapshots. No more manual exports.</Card.Description\n    >\n  </Card.Header>\n  <Card.Content>\n    <ul class=\"grid gap-2 py-2 text-sm\">\n      {#each steps as step (step)}\n        <li class=\"flex gap-2\">\n          <ChevronRightIcon\n            class=\"mt-0.5 size-4 shrink-0 text-muted-foreground\"\n          />\n          <span>{step}</span>\n        </li>\n      {/each}\n    </ul>\n  </Card.Content>\n  <Card.Footer class=\"flex-col gap-2\">\n    <Button size=\"sm\" class=\"w-full\">Set up scheduled reports</Button>\n    <Button variant=\"outline\" size=\"sm\" class=\"w-full\">See what's new</Button>\n  </Card.Footer>\n</Card.Root>", "cs": "https://www.shadcn-svelte.com/docs/components/card#size", "cl": "MIT", "sup": "# 聚合站补充 · Hub notes\n# 原站文档 Docs: https://www.shadcn-svelte.com/docs/components/card#size\n# 许可 License: MIT\n# 以上「原站原文」逐字来自官方仓库/文档（每段标了来源）；完整变体与 API 请看原站。\n# 本站不提供任何付费模板 / Pro 组件源码。", "full": 1}, "cs2-lib-primevue-org--color--colorpicker--v2": {"d": "ColorPicker is an input component to select a color.", "ds": "https://primevue.dev/colorpicker/", "c": "# ① 安装 Install — https://github.com/primefaces/primevue/blob/HEAD/apps/showcase/doc/vite/DownloadDoc.vue\n# Using npm\nnpm install primevue @primeuix/themes\n\n# Using yarn\nyarn add primevue @primeuix/themes\n\n# Using pnpm\npnpm add primevue @primeuix/themes\n\n// ② 配置 Setup · Theme — https://github.com/primefaces/primevue/blob/HEAD/apps/showcase/doc/vite/ThemeDoc.vue\nimport { createApp } from 'vue';\nimport PrimeVue from 'primevue/config';\nimport Aura from '@primeuix/themes/aura';\n\nconst app = createApp(App);\napp.use(PrimeVue, {\n    theme: {\n        preset: Aura\n    }\n});\n\n// ③ 引入 Import — https://github.com/primefaces/primevue/blob/HEAD/apps/showcase/doc/colorpicker/ImportDoc.vue\nimport ColorPicker from 'primevue/colorpicker';\n\n<!-- ④ 示例 Example · Basic · Composition API — https://github.com/primefaces/primevue/blob/HEAD/apps/showcase/doc/colorpicker/BasicDoc.vue -->\n<template>\n    <div class=\"card flex justify-center\">\n        <ColorPicker v-model=\"color\" />\n    </div>\n</template>\n\n<script setup>\nimport { ref } from \"vue\";\n\nconst color = ref();\n</script>", "cs": "https://github.com/primefaces/primevue/blob/HEAD/apps/showcase/doc/colorpicker/BasicDoc.vue", "cl": "MIT", "sup": "# 聚合站补充 · Hub notes\n# 原站文档 Docs: https://primevue.dev/colorpicker/#__nuxt\n# 许可 License: MIT · 框架 Framework: Vue\n# 以上「原站原文」逐字来自官方仓库/文档（每段标了来源）；完整变体与 API 请看原站。\n# 不含付费部分：PrimeVue LTS、PrimeBlocks、付费模板（请到原站购买）。", "fw": "Vue", "full": 1}, "cs2-lib-www-skeleton-dev--avatar--avatar--v2": {"d": "An image with a fallback for representing the user.", "ds": "https://www.skeleton.dev/docs/svelte/framework-components/avatar", "c": "import { Avatar } from '@skeletonlabs/skeleton-react';\n\nexport default function Default() {\n\treturn (\n\t\t<div className=\"flex items-center gap-8\">\n\t\t\t{/* Small */}\n\t\t\t<Avatar className=\"size-10\">\n\t\t\t\t<Avatar.Image src=\"https://i.pravatar.cc/40?img=48\" alt=\"small\" />\n\t\t\t\t<Avatar.Fallback>SK</Avatar.Fallback>\n\t\t\t</Avatar>\n\t\t\t{/* Base */}\n\t\t\t<Avatar>\n\t\t\t\t<Avatar.Image src=\"https://i.pravatar.cc/60?img=48\" alt=\"base\" />\n\t\t\t\t<Avatar.Fallback>SK</Avatar.Fallback>\n\t\t\t</Avatar>\n\t\t\t{/* Large */}\n\t\t\t<Avatar className=\"size-20\">\n\t\t\t\t<Avatar.Image src=\"https://i.pravatar.cc/80?img=48\" alt=\"large\" />\n\t\t\t\t<Avatar.Fallback>SK</Avatar.Fallback>\n\t\t\t</Avatar>\n\t\t</div>\n\t);\n}\n\nimport { Avatar } from '@skeletonlabs/skeleton-react';\n\nexport default function Filter() {\n\treturn (\n\t\t<>\n\t\t\t<Avatar>\n\t\t\t\t<Avatar.Image src=\"https://i.pravatar.cc/150?img=48\" className=\"filter-[url(#apollo)]\" alt=\"filtered\" />\n\t\t\t\t<Avatar.Fallback>SK</Avatar.Fallback>\n\t\t\t</Avatar>\n\t\t\t<svg className=\"absolute -left-full w-0 h-0\">\n\t\t\t\t<filter id=\"apollo\" filterUnits=\"objectBoundingBox\" primitiveUnits=\"userSpaceOnUse\" colorInterpolationFilters=\"sRGB\">\n\t\t\t\t\t<feColorMatrix\n\t\t\t\t\t\tvalues=\"0.8 0.6 -0.4 0.1 0,\n            0 1.2 0.05 0 0,\n            0 -1 3 0.02 0,\n            0 0 0 50 0\"\n\t\t\t\t\t\tresult=\"final\"\n\t\t\t\t\t\tin=\"SourceGraphic\"\n\t\t\t\t\t/>\n\t\t\t\t</filter>\n\t\t\t</svg>\n\t\t</>\n\t);\n}", "cs": "https://www.skeleton.dev/docs/svelte/framework-components/avatar", "cl": "MIT", "sup": "# 聚合站补充 · Hub notes\n# 原站文档 Docs: https://www.skeleton.dev/docs/svelte/framework-components/avatar\n# 许可 License: MIT\n# 以上「原站原文」逐字来自官方仓库/文档（每段标了来源）；完整变体与 API 请看原站。\n# 本站不提供任何付费模板 / Pro 组件源码。"}, "cs2-lib-ant-design--checkbox--radio--v1": {"d": "Used to select a single state from multiple options.", "ds": "https://ant.design/components/radio", "c": "# ① 安装 Install — https://github.com/ant-design/ant-design/blob/HEAD/README.md\nnpm install antd\n\n// ④ 示例 Example · basic.tsx — https://github.com/ant-design/ant-design/blob/HEAD/components/radio/demo/basic.tsx\nimport React from 'react';\nimport { Radio } from 'antd';\n\nconst App: React.FC = () => <Radio>Radio</Radio>;\n\nexport default App;", "cs": "https://github.com/ant-design/ant-design/blob/HEAD/components/radio/demo/basic.tsx", "cl": "MIT", "sup": "# 聚合站补充 · Hub notes\n# 原站文档 Docs: https://ant.design/components/radio#radio-demo-basic\n# 许可 License: MIT · 框架 Framework: React\n# 以上「原站原文」逐字来自官方仓库/文档（每段标了来源）；完整变体与 API 请看原站。\n# 本站不提供任何付费模板 / Pro 组件源码。", "fw": "React", "full": 1}, "cs2-lib-primeng-org--table--table--v0": {"d": "Table displays data in tabular format.", "ds": "https://primeng.dev/table", "sup": "# 聚合站补充 · Hub notes\n# 原站文档 Docs: https://primeng.dev/table\n# 许可 License: MIT · 框架 Framework: Angular\n# 以上「原站原文」逐字来自官方仓库/文档（每段标了来源）；完整变体与 API 请看原站。\n# 不含付费部分：PrimeNG LTS（-lts 版本为商业许可）、PrimeBlocks、付费模板（请到原站购买）。", "c": "# ① 安装 Install — https://github.com/primefaces/primeng/blob/HEAD/apps/showcase/doc/installation/download-doc.ts\n# Using npm\nnpm install primeng @primeuix/themes\n\n# Using yarn\nyarn add primeng @primeuix/themes\n\n# Using pnpm\npnpm add primeng @primeuix/themes\n\n// ② 配置 Setup · Theme — https://github.com/primefaces/primeng/blob/HEAD/apps/showcase/doc/installation/theme-doc.ts\nimport { ApplicationConfig } from '@angular/core';\nimport { provideAnimationsAsync } from '@angular/platform-browser/animations/async';\nimport { providePrimeNG } from 'primeng/config';\nimport Aura from '@primeuix/themes/aura';\n\nexport const appConfig: ApplicationConfig = {\n    providers: [\n        provideAnimationsAsync(),\n        providePrimeNG({\n            theme: Aura\n        })\n    ]\n};\n\n// ③ 引入 Import — https://github.com/primefaces/primeng/blob/HEAD/apps/showcase/doc/table/import-doc.ts\nimport { TableModule } from 'primeng/table';\n\n// ④ 示例 Example · Basic（官方 basic-doc.ts，已去掉文档页外壳 app-docsectiontext / app-code） — https://github.com/primefaces/primeng/blob/HEAD/apps/showcase/doc/table/basic-doc.ts\nimport { DeferredDemo } from '@/components/demo/deferreddemo';\nimport { Product } from '@/domain/product';\nimport { ProductService } from '@/service/productservice';\nimport { ChangeDetectionStrategy, ChangeDetectorRef, Component } from '@angular/core';\nimport { Table, TableModule, TablePassThrough } from 'primeng/table';\n\n@Component({\n    selector: 'table-basic-demo',\n    standalone: true,\n    imports: [TableModule, DeferredDemo],\n    template: `\n        <p-deferred-demo (load)=\"loadDemoData()\">\n            <div class=\"card\">\n                <p-table [value]=\"products\" [tableStyle]=\"{ 'min-width': '50rem' }\">\n                    <ng-template #header>\n                        <tr>\n                            <th>Code</th>\n                            <th>Name</th>\n                            <th>Category</th>\n                            <th>Quantity</th>\n                        </tr>\n                    </ng-template>\n                    <ng-template #body let-product>\n                        <tr>\n                            <td>{{ product.code }}</td>\n                            <td>{{ product.name }}</td>\n                            <td>{{ product.category }}</td>\n                            <td>{{ product.quantity }}</td>\n                        </tr>\n                    </ng-template>\n                </p-table>\n            </div>\n        </p-deferred-demo>`,\n    changeDetection: ChangeDetectionStrategy.OnPush\n})\nexport class TableBasicDemo {\n    products!: Product[];\n\n    table: Table;\n    pt: TablePassThrough;\n\n    constructor(\n        private productService: ProductService,\n        private cd: ChangeDetectorRef\n    ) {}\n\n    loadDemoData() {\n        this.productService.getProductsMini().then((data) => {\n            this.products = data;\n            this.cd.markForCheck();\n        });\n    }\n}", "cs": "https://github.com/primefaces/primeng/blob/HEAD/apps/showcase/doc/table/basic-doc.ts", "cl": "MIT", "fw": "Angular", "full": 1}, "cs2-lib-tdesign-tencent-com--slider--slider--v0": {"sup": "# 聚合站补充 · Hub notes\n# 原站文档 Docs: https://tdesign.tencent.com/vue-next/components/slider#横向滑块\n# 许可 License: MIT · 框架 Framework: Vue\n# 以上「原站原文」逐字来自官方仓库/文档（每段标了来源）；完整变体与 API 请看原站。\n# 本站不提供任何付费模板 / Pro 组件源码。", "d": "Slider 滑块：滑块（滑动型输入器），是帮助用户在连续或间断的区间内，通过滑动来选择合适数值（一个数值或范围数值）的控件。\n\n### 基础滑块\n由游标和滑动轴组成的基础滑块，有单游标滑块和双游标两种类型。布局方向可分为横向滑块和纵向滑块。", "ds": "https://github.com/Tencent/tdesign-common/blob/develop/docs/web/api/slider.md", "c": "# ① 安装 Install — https://github.com/Tencent/tdesign-vue-next#readme\nnpm i tdesign-vue-next\n\n// ② 配置 Setup · main.js — https://github.com/Tencent/tdesign-vue-next#readme\nimport { createApp } from 'vue';\nimport { Button } from 'tdesign-vue-next';\n\nimport 'tdesign-vue-next/es/style/index.css';\n\nimport App from './app.vue';\n\nconst app = createApp(App);\napp.use(Button);\n\n<!-- ④ 示例 Example · base.vue — https://github.com/Tencent/tdesign-vue-next/blob/HEAD/packages/components/slider/_example/base.vue -->\n<template>\n  <t-space direction=\"vertical\" class=\"slider-demo-container\">\n    <t-slider v-model=\"value1\" @change-end=\"onChangeEnd\" />\n\n    <t-slider v-model=\"value2\" range @change-end=\"onChangeEnd\" />\n  </t-space>\n</template>\n<script lang=\"ts\" setup>\nimport { ref } from 'vue';\nimport type { SliderProps } from 'tdesign-vue-next';\n\nconst value1 = ref(12);\nconst value2 = ref([30, 70]);\nconst onChangeEnd: SliderProps['onChangeEnd'] = (value) => {\n  console.log('change end value', value);\n};\n</script>\n<style>\n.slider-demo-container {\n  padding: 30px 24px;\n}\n</style>", "cs": "https://github.com/Tencent/tdesign-vue-next/blob/HEAD/packages/components/slider/_example/base.vue", "cl": "MIT", "fw": "Vue", "full": 1}, "cs2-lib-chakra-ui-com--alert--alert--v0": {"d": "Used to communicate a state that affects a system, feature or page.", "ds": "https://chakra-ui.com/docs/components/alert", "c": "# ① 安装 Install — https://github.com/chakra-ui/chakra-ui#readme\nnpm install @chakra-ui/react @emotion/react\n\n// ④ 示例 Example · 官方文档示例 — https://chakra-ui.com/docs/components/alert\nimport { Alert } from \"@chakra-ui/react\"\n\nimport { Alert as ChakraAlert } from \"@chakra-ui/react\"\nimport * as React from \"react\"\n\nexport interface AlertProps extends Omit<ChakraAlert.RootProps, \"title\"> {\n  startElement?: React.ReactNode\n  endElement?: React.ReactNode\n  title?: React.ReactNode\n  icon?: React.ReactElement\n}\n\nexport const AlertClosedComponent = React.forwardRef<\n  HTMLDivElement,\n  AlertProps\n>(function Alert(props, ref) {\n  const { title, children, icon, startElement, endElement, ...rest } = props\n  return (\n    <ChakraAlert.Root ref={ref} {...rest}>\n      {startElement || <ChakraAlert.Indicator>{icon}</ChakraAlert.Indicator>}\n      {children ? (\n        <ChakraAlert.Content>\n          <ChakraAlert.Title>{title}</ChakraAlert.Title>\n          <ChakraAlert.Description>{children}</ChakraAlert.Description>\n        </ChakraAlert.Content>\n      ) : (\n        <ChakraAlert.Title flex=\"1\">{title}</ChakraAlert.Title>\n      )}\n      {endElement}\n    </ChakraAlert.Root>\n  )\n})", "cs": "https://chakra-ui.com/docs/components/alert", "cl": "MIT", "sup": "# 聚合站补充 · Hub notes\n# 原站文档 Docs: https://chakra-ui.com/docs/components/alert\n# 许可 License: MIT\n# 以上「原站原文」逐字来自官方仓库/文档（每段标了来源）；完整变体与 API 请看原站。\n# 本站不提供任何付费模板 / Pro 组件源码。", "full": 1}, "cs2-lib-ui-nuxt-com--select--select--v2": {"d": "A select element to choose from a list of options.", "ds": "https://ui.nuxt.com/docs/components/select", "c": "# ① 安装 Install — https://github.com/nuxt/ui#readme\nnpm install @nuxt/ui\n\n<!-- ④ 示例 Example · 官方文档示例 — https://ui.nuxt.com/docs/components/select#position -->\n<script setup lang=\"ts\">\nconst items = ref(['Backlog', 'Todo', 'In Progress', 'Done'])\nconst value = ref('Backlog')\n</script>\n\n<template>\n  <USelect v-model=\"value\" :items=\"items\" />\n</template>\n\n<script setup lang=\"ts\">\nimport { ref } from 'vue'\n\nconst items = ref(['Backlog', 'Todo', 'In Progress', 'Done'])\nconst value = ref('Todo')\n</script>\n\n<template>\n  <USelect\n    v-model=\"value\"\n    :content=\"{\n      position: 'item-aligned'\n    }\"\n    :items=\"items\"\n    class=\"w-48\"\n  />\n</template>", "cs": "https://ui.nuxt.com/docs/components/select#position", "cl": "MIT", "sup": "# 聚合站补充 · Hub notes\n# 原站文档 Docs: https://ui.nuxt.com/docs/components/select#position\n# 许可 License: MIT\n# 以上「原站原文」逐字来自官方仓库/文档（每段标了来源）；完整变体与 API 请看原站。\n# 本站不提供任何付费模板 / Pro 组件源码。", "full": 1}, "cs2-lib-quasar-dev--carousel--carousel--v0": {"d": "The QCarousel Vue component allows you to display a series of slides, useful for wizards or an image gallery.", "ds": "https://quasar.dev/vue-components/carousel/", "c": "# ① 安装 Install — https://github.com/quasarframework/quasar/blob/HEAD/docs/src/pages/start/quick-start.md\npnpm create quasar@latest\n# or\nnpm init quasar@latest\n\n<!-- ④ 示例 Example · Basic.vue — https://github.com/quasarframework/quasar/blob/HEAD/docs/src/examples/QCarousel/Basic.vue -->\n<template>\n  <div class=\"q-pa-md\">\n    <q-carousel\n      v-model=\"slide\"\n      transition-prev=\"slide-right\"\n      transition-next=\"slide-left\"\n      animated\n      control-color=\"primary\"\n      class=\"rounded-borders\"\n    >\n      <q-carousel-slide name=\"style\" class=\"column no-wrap flex-center\">\n        <q-icon name=\"style\" color=\"primary\" size=\"56px\" />\n        <div class=\"q-mt-md text-center\">\n          {{ lorem }}\n        </div>\n      </q-carousel-slide>\n      <!-- #region -->\n      <q-carousel-slide name=\"tv\" class=\"column no-wrap flex-center\">\n        <q-icon name=\"live_tv\" color=\"primary\" size=\"56px\" />\n        <div class=\"q-mt-md text-center\">\n          {{ lorem }}\n        </div>\n      </q-carousel-slide>\n      <q-carousel-slide name=\"layers\" class=\"column no-wrap flex-center\">\n        <q-icon name=\"layers\" color=\"primary\" size=\"56px\" />\n        <div class=\"q-mt-md text-center\">\n          {{ lorem }}\n        </div>\n      </q-carousel-slide>\n      <q-carousel-slide name=\"map\" class=\"column no-wrap flex-center\">\n        <q-icon name=\"terrain\" color=\"primary\" size=\"56px\" />\n        <div class=\"q-mt-md text-center\">\n          {{ lorem }}\n        </div>\n      </q-carousel-slide>\n      <!-- #endregion -->\n    </q-carousel>\n\n    <div class=\"row justify-center\">\n      <q-btn-toggle\n        glossy\n        v-model=\"slide\"\n        :options=\"[\n          { label: 1, value: 'style' },\n          { label: 2, value: 'tv' },\n          { label: 3, value: 'layers' },\n          { label: 4, value: 'map' }\n        ]\"\n      />\n    </div>\n  </div>\n</template>\n\n<script setup>\nimport { ref } from 'vue'\n\nconst slide = ref('style')\nconst lorem =\n  'Lorem ipsum dolor, sit amet consectetur adipisicing elit. Itaque voluptatem totam, architecto cupiditate officia rerum, error dignissimos praesentium libero ab nemo provident incidunt ducimus iusto perferendis porro earum. Totam, numquam?'\n</script>", "cs": "https://github.com/quasarframework/quasar/blob/HEAD/docs/src/examples/QCarousel/Basic.vue", "cl": "MIT", "fw": "Vue", "full": 1, "sup": "# 聚合站补充 · Hub notes\n# 原站文档 Docs: https://quasar.dev/vue-components/carousel/#example--basic--basic\n# 许可 License: MIT · 框架 Framework: Vue\n# 以上「原站原文」逐字来自官方仓库/文档（每段标了来源）；完整变体与 API 请看原站。\n# 本站不提供任何付费模板 / Pro 组件源码。"}, "cs2-lib-ng-ant-design--alert--alert--v1": {"d": "When To Use#\nWhen you need to show alert messages to users.\nWhen you need a persistent static container which is closable by user actions.", "ds": "https://ng.ant.design/components/alert/en", "sup": "# 聚合站补充 · Hub notes\n# 原站文档 Docs: https://ng.ant.design/components/alert/en#components-alert-demo-basic\n# 许可 License: MIT · 框架 Framework: Angular\n# 以上「原站原文」逐字来自官方仓库/文档（每段标了来源）；完整变体与 API 请看原站。\n# 本站不提供任何付费模板 / Pro 组件源码。", "c": "# ① 安装 Install — https://github.com/NG-ZORRO/ng-zorro-antd/blob/HEAD/README.md\nng add ng-zorro-antd\n\n// ④ 示例 Example · basic.ts — https://github.com/NG-ZORRO/ng-zorro-antd/blob/HEAD/components/alert/demo/basic.ts\nimport { Component } from '@angular/core';\n\nimport { NzAlertModule } from 'ng-zorro-antd/alert';\n\n@Component({\n  selector: 'nz-demo-alert-basic',\n  imports: [NzAlertModule],\n  template: `<nz-alert nzType=\"success\" nzMessage=\"Success Text\" />`\n})\nexport class NzDemoAlertBasicComponent {}", "cs": "https://github.com/NG-ZORRO/ng-zorro-antd/blob/HEAD/components/alert/demo/basic.ts", "cl": "MIT", "fw": "Angular", "full": 1}, "cs2-lib-element-plus-org--checkbox--checkbox--v2": {"d": "A group of options for multiple choices.", "ds": "https://element-plus.org/en-US/component/checkbox.html", "c": "# ① 安装 Install — https://github.com/element-plus/element-plus/blob/dev/docs/en-US/guide/installation.md\n$ npm install element-plus --save\n\n// ② 配置 Setup · main.ts（Full import） — https://github.com/element-plus/element-plus/blob/dev/docs/en-US/guide/quickstart.md\nimport { createApp } from 'vue'\nimport ElementPlus from 'element-plus'\nimport 'element-plus/dist/index.css'\nimport App from './App.vue'\n\nconst app = createApp(App)\n\napp.use(ElementPlus)\napp.mount('#app')\n\n<!-- ④ 示例 Example · grouping.vue — https://github.com/element-plus/element-plus/blob/dev/docs/examples/checkbox/grouping.vue -->\n<template>\n  <el-checkbox-group v-model=\"checkList\">\n    <el-checkbox label=\"Option A\" value=\"Value A\" />\n    <el-checkbox label=\"Option B\" value=\"Value B\" />\n    <el-checkbox label=\"Option C\" value=\"Value C\" />\n    <el-checkbox label=\"disabled\" value=\"Value disabled\" disabled />\n    <el-checkbox\n      label=\"selected and disabled\"\n      value=\"Value selected and disabled\"\n      disabled\n    />\n  </el-checkbox-group>\n</template>\n\n<script lang=\"ts\" setup>\nimport { ref } from 'vue'\n\nconst checkList = ref(['Value selected and disabled', 'Value A'])\n</script>", "cs": "https://github.com/element-plus/element-plus/blob/dev/docs/examples/checkbox/grouping.vue", "cl": "MIT", "sup": "# 聚合站补充 · Hub notes\n# 原站文档 Docs: https://element-plus.org/en-US/component/checkbox.html#checkbox-group\n# 许可 License: MIT · 框架 Framework: Vue\n# 以上「原站原文」逐字来自官方仓库/文档（每段标了来源）；完整变体与 API 请看原站。\n# 本站不提供任何付费模板 / Pro 组件源码。", "fw": "Vue", "full": 1}, "cs2-lib-arco-design--empty--result--v1": {"d": "用于反馈一系列操作任务的处理结果，当有重要操作需告知用户处理结果，且反馈内容较为复杂时使用。", "ds": "https://arco.design/react/components/result", "c": "# ① 安装 Install — https://github.com/arco-design/arco-design/blob/HEAD/README.md\nnpm install @arco-design/web-react\n\n// ④ 示例 Example · basic.md — https://github.com/arco-design/arco-design/blob/HEAD/components/Result/__demo__/basic.md\nimport { Result, Button } from '@arco-design/web-react';\n\nconst App = () => {\n  return (\n    <div>\n      <Result\n        status=\"success\"\n        title=\"Success message\"\n        subTitle=\"This is a success description.\"\n        extra={[\n          <Button key=\"again\" type=\"secondary\" style={{ margin: '0 16px' }}>\n            Again\n          </Button>,\n          <Button key=\"back\" type=\"primary\">\n            Back\n          </Button>,\n        ]}\n      ></Result>\n    </div>\n  );\n};\n\nexport default App;", "cs": "https://github.com/arco-design/arco-design/blob/HEAD/components/Result/__demo__/basic.md", "cl": "MIT", "sup": "# 聚合站补充 · Hub notes\n# 原站文档 Docs: https://arco.design/react/components/result#Success\n# 许可 License: MIT · 框架 Framework: React\n# 以上「原站原文」逐字来自官方仓库/文档（每段标了来源）；完整变体与 API 请看原站。\n# 本站不提供任何付费模板 / Pro 组件源码。", "fw": "React", "full": 1}, "cs2-lib-www-naiveui-com--progress--progress--v1": {"d": "I have no words to say but there still should be a placeholder to make layout looks spread.", "ds": "https://www.naiveui.com/en-US/os-theme/components/progress", "sup": "# 聚合站补充 · Hub notes\n# 原站文档 Docs: https://www.naiveui.com/en-US/os-theme/components/progress\n# 许可 License: MIT · 框架 Framework: Vue\n# 以上「原站原文」逐字来自官方仓库/文档（每段标了来源）；完整变体与 API 请看原站。\n# 本站不提供任何付费模板 / Pro 组件源码。", "c": "# ① 安装 Install — https://github.com/tusen-ai/naive-ui/blob/HEAD/README.md\nnpm i naive-ui\n\n<!-- ④ 示例 Example · circle.demo.vue — https://github.com/tusen-ai/naive-ui/blob/HEAD/src/progress/demos/enUS/circle.demo.vue -->\n<script lang=\"ts\" setup>\nimport { ref } from 'vue'\n\nconst percentage = ref(0)\n\nfunction add() {\n  percentage.value += 10\n  if (percentage.value > 100) {\n    percentage.value = 0\n  }\n}\n\nfunction minus() {\n  percentage.value -= 10\n  if (percentage.value < 0) {\n    percentage.value = 100\n  }\n}\n</script>\n\n<template>\n  <n-space vertical>\n    <n-space>\n      <n-progress type=\"circle\" :percentage=\"percentage\" />\n      <n-progress type=\"circle\" status=\"info\" :percentage=\"percentage\" />\n      <n-progress type=\"circle\" status=\"success\" :percentage=\"percentage\" />\n      <n-progress type=\"circle\" status=\"warning\" :percentage=\"percentage\" />\n      <n-progress type=\"circle\" status=\"error\" :percentage=\"percentage\" />\n    </n-space>\n    <n-space>\n      <n-button @click=\"minus\">\n        Minus 10%\n      </n-button>\n      <n-button @click=\"add\">\n        Add 10%\n      </n-button>\n    </n-space>\n  </n-space>\n</template>", "cs": "https://github.com/tusen-ai/naive-ui/blob/HEAD/src/progress/demos/enUS/circle.demo.vue", "cl": "MIT", "fw": "Vue", "full": 1}, "cs2-lib-shoelace-style--checkbox--radio-group--v0": {"d": "<sl-radio-group> | SlRadioGroup", "ds": "https://shoelace.style/components/radio-group", "c": "# ① 安装 Install — https://github.com/shoelace-style/shoelace#readme\nnpm install @shoelace-style/shoelace\n\n// ④ 示例 Example · 官方文档示例 — https://shoelace.style/components/radio-group\nimport SlRadio from '@shoelace-style/shoelace/dist/react/radio';\nimport SlRadioGroup from '@shoelace-style/shoelace/dist/react/radio-group';\n\nconst App = () => (\n  <SlRadioGroup label=\"Select an option\" name=\"a\" value=\"1\">\n    <SlRadio value=\"1\">Option 1</SlRadio>\n    <SlRadio value=\"2\">Option 2</SlRadio>\n    <SlRadio value=\"3\">Option 3</SlRadio>\n  </SlRadioGroup>\n);", "cs": "https://shoelace.style/components/radio-group", "cl": "MIT", "sup": "# 聚合站补充 · Hub notes\n# 原站文档 Docs: https://shoelace.style/components/radio-group\n# 许可 License: MIT\n# 以上「原站原文」逐字来自官方仓库/文档（每段标了来源）；完整变体与 API 请看原站。\n# 本站不提供任何付费模板 / Pro 组件源码。", "full": 1}, "cs2-lib-material-web-dev--input--text-field--v0": {"d": "Text fields let users enter text into a UI.", "ds": "https://material-web.dev/components/text-field/", "c": "# ① 安装 Install — https://github.com/material-components/material-web/blob/main/docs/quick-start.md\nnpm install @material/web\n\n// ③ 引入 Import — https://github.com/material-components/material-web/blob/main/docs/quick-start.md\n// index.js\nimport '@material/web/button/filled-button.js';\nimport '@material/web/button/outlined-button.js';\nimport '@material/web/checkbox/checkbox.js';\n\n<!-- ④ 示例 Example · text-field.md · Usage — https://github.com/material-components/material-web/blob/main/docs/components/text-field.md -->\n<md-filled-text-field label=\"Label\" value=\"Value\">\n</md-filled-text-field>\n\n<md-outlined-text-field label=\"Label\" value=\"Value\">\n</md-outlined-text-field>", "cs": "https://github.com/material-components/material-web/blob/main/docs/components/text-field.md", "cl": "Apache-2.0", "sup": "# 聚合站补充 · Hub notes\n# 原站文档 Docs: https://material-web.dev/components/text-field/\n